def transform(grid):
    h, w = len(grid), len(grid[0])
    slots = [j for j in range(w) if j % 3 == 1]
    base = [max({grid[i][j] for i in range(h)}, key=lambda v: sum(grid[i][j]==v for i in range(h))) for j in range(w)]
    sigs = [tuple(i for i in range(h) if grid[i][j] != base[j]) for j in slots]
    order = sorted(range(len(slots)), key=lambda k: (-len(sigs[k]), k))
    out = [row[:] for row in grid]
    for newk, oldk in enumerate(order):
        j = slots[newk]; s = set(sigs[oldk])
        for i in range(h):
            out[i][j] = 0 if i in s else base[j]
    return out

